// The capture trigger scripts the Rust runtime installs, generated byte for
// byte as Rust generates them (rust/crates/store/src/feed.rs
// `capture_triggers_sql`, record_views.rs `capture_triggers_sql` and
// `owned_capture_triggers_sql_named`).
//
// These scripts still call `gonvex_capture` and `gonvex_record_value`. They are
// the "Rust form": their SHA-256 is the `_gonvex_sync_bootstrap` receipt, as in
// Rust, and `images.ts` turns them into the plain SQL a Durable Object accepts.

import { quoteIdentifier } from "./sql.ts";

export const CAPTURE_FUNCTION = "gonvex_capture";
export const VALUE_FUNCTION = "gonvex_record_value";

/** feed.rs `capture_trigger_names`. */
export function captureTriggerNames(table: string): [string, string, string] {
  return [`_gonvex_sync_${table}_insert`, `_gonvex_sync_${table}_update`, `_gonvex_sync_${table}_delete`];
}

/** Trigger names of one record dependency (provision.rs). */
export function dependencyTriggerNames(namespace: string): [string, string, string] {
  return [`gonvex_record_dependency_${namespace}_insert`, `gonvex_record_dependency_${namespace}_update`, `gonvex_record_dependency_${namespace}_delete`];
}

const literal = (value: string) => value.replace(/'/g, "''");

/** feed.rs `capture_triggers_sql`: AFTER triggers staging `[old, new, changed]` for an entity table. */
export function entityCaptureSql(table: string, key: string): string {
  const quotedTable = quoteIdentifier(table);
  const literalTable = literal(table);
  const keyNew = `CAST(NEW.${quoteIdentifier(key)} AS TEXT)`;
  const keyOld = `CAST(OLD.${quoteIdentifier(key)} AS TEXT)`;
  const [insert, update, del] = captureTriggerNames(table).map(quoteIdentifier) as [string, string, string];
  const body = (rowKey: string, operation: string, rowid: string, op: number) =>
    `INSERT INTO _gonvex_sync_changes (table_name, row_id, operation, new_value)\n  ` +
    `VALUES ('${literalTable}', ${rowKey}, '${operation}', ${CAPTURE_FUNCTION}('${literalTable}', ${rowid}, ${op}));`;
  return (
    `DROP TRIGGER IF EXISTS ${insert};\nDROP TRIGGER IF EXISTS ${update};\nDROP TRIGGER IF EXISTS ${del};\n` +
    `CREATE TRIGGER ${insert} AFTER INSERT ON ${quotedTable} BEGIN\n  ${body(keyNew, "insert", "NEW.rowid", 0)}\nEND;\n` +
    `CREATE TRIGGER ${update} AFTER UPDATE ON ${quotedTable} BEGIN\n  ${body(keyNew, "update", "NEW.rowid", 1)}\nEND;\n` +
    `CREATE TRIGGER ${del} AFTER DELETE ON ${quotedTable} BEGIN\n  ${body(keyOld, "delete", "OLD.rowid", 2)}\nEND;\n`
  );
}

/** record_views.rs `capture_triggers_sql`: BEFORE triggers staging the first pre-image of a logical record. */
export function recordCaptureSql(storage: string, key: string, name: string, integerKey: boolean): string {
  const [insert, update, del] = captureTriggerNames(storage).map(quoteIdentifier) as [string, string, string];
  const pub = (row: string) =>
    integerKey ? `(SELECT value FROM _gonvex_identity_keys WHERE _id=${row}.${quoteIdentifier(key)})` : `CAST(${row}.${quoteIdentifier(key)} AS TEXT)`;
  const lit = literal(name);
  const stage = (row: string) => {
    const k = pub(row);
    return `INSERT INTO _gonvex_record_pending(table_name,row_id,old_value) SELECT '${lit}',${k},${VALUE_FUNCTION}('${lit}',${k}) WHERE NOT EXISTS(SELECT 1 FROM _gonvex_record_pending WHERE table_name='${lit}' AND row_id=${k});`;
  };
  const q = quoteIdentifier(storage);
  return `DROP TRIGGER IF EXISTS ${insert};\nDROP TRIGGER IF EXISTS ${update};\nDROP TRIGGER IF EXISTS ${del};\nCREATE TRIGGER ${insert} BEFORE INSERT ON ${q} BEGIN\n${stage("NEW")}\nEND;\nCREATE TRIGGER ${update} BEFORE UPDATE ON ${q} BEGIN\n${stage("OLD")}\nEND;\nCREATE TRIGGER ${del} BEFORE DELETE ON ${q} BEGIN\n${stage("OLD")}\nEND;\n`;
}

/** What record_views.rs reads from a `_gonvex_record_views` row. */
export interface RecordOwner {
  name: string;
  storageTable: string;
  keyColumn: string;
}

/**
 * record_views.rs `owned_capture_triggers_sql_named`: BEFORE triggers on an
 * owned table (or a record dependency's source, with `dependency`) that stage
 * the owning record's pre-image.
 */
export function ownedCaptureSql(
  source: string,
  sourceKey: string,
  owner: RecordOwner,
  column: string,
  inbound: boolean,
  integerKey: boolean,
  dependency?: { namespace: string; watch: readonly string[] },
): string {
  const watch = dependency?.watch ?? [];
  const names = (dependency ? dependencyTriggerNames(dependency.namespace) : captureTriggerNames(source)).map(quoteIdentifier);
  const lit = literal(owner.name);
  const stage = (row: string) => {
    const priv = inbound ? `r.${quoteIdentifier(owner.keyColumn)}` : `${row}.${quoteIdentifier(column)}`;
    const pub = integerKey ? `(SELECT value FROM _gonvex_identity_keys WHERE _id=${priv})` : `CAST(${priv} AS TEXT)`;
    const from = inbound ? ` FROM ${quoteIdentifier(owner.storageTable)} r` : "";
    const predicate = inbound ? `r.${quoteIdentifier(column)}=${row}.${quoteIdentifier(sourceKey)} AND ` : "";
    return `INSERT INTO _gonvex_record_pending(table_name,row_id,old_value) SELECT '${lit}',${pub},${VALUE_FUNCTION}('${lit}',${pub})${from} WHERE ${priv} IS NOT NULL AND ${predicate}NOT EXISTS(SELECT 1 FROM _gonvex_record_pending WHERE table_name='${lit}' AND row_id=${pub});`;
  };
  const update = watch.length === 0 ? "UPDATE" : `UPDATE OF ${watch.map(quoteIdentifier).join(",")}`;
  const updateWhen = watch.length === 0 ? "" : ` WHEN ${watch.map((c) => `NEW.${quoteIdentifier(c)} IS NOT OLD.${quoteIdentifier(c)}`).join(" OR ")}`;
  const events: Array<[string, string]> = [
    ["INSERT", stage("NEW")],
    [update, `${stage("OLD")} ${stage("NEW")}`],
    ["DELETE", stage("OLD")],
  ];
  return events
    .map(([event, body], index) => {
      const name = names[index]!;
      return `DROP TRIGGER IF EXISTS ${name};\nCREATE TRIGGER ${name} BEFORE ${event} ON ${quoteIdentifier(source)}${event.startsWith("UPDATE") ? updateWhen : ""} BEGIN\n${body}\nEND;\n`;
    })
    .join("");
}

/**
 * provision.rs `trigger_statements`: the `CREATE TRIGGER … END` statements of
 * an install script, as SQLite stores them in `sqlite_schema.sql`.
 */
export function triggerStatements(script: string): string[] {
  const CREATE = "CREATE TRIGGER ";
  const END = "\nEND;";
  const found: string[] = [];
  let rest = script;
  for (;;) {
    const start = rest.indexOf(CREATE);
    if (start < 0) break;
    const candidate = rest.slice(start);
    const end = candidate.indexOf(END);
    if (end < 0) break;
    found.push(candidate.slice(0, end + END.length - 1));
    rest = candidate.slice(end + END.length);
  }
  return found;
}
